test "cli_truncate: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-truncate" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqual(@as(usize, 0), o.files.len);
    try std.testing.expectEqual(false, o.no_create);
    try std.testing.expect(o.ref == null);
    try std.testing.expect(o.size == null);
}

